package dev.redstoneengineering.block;
import com.mojang.serialization.MapCodec;import dev.redstoneengineering.RedstoneEngineering;import net.minecraft.core.BlockPos;import net.minecraft.core.Direction;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerLevel;import net.minecraft.util.RandomSource;import net.minecraft.world.InteractionResult;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.BlockGetter;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.Block;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.level.block.state.StateDefinition;import net.minecraft.world.level.block.state.properties.IntegerProperty;import net.minecraft.world.phys.BlockHitResult;
/** Base-mounted tank probe: counts contiguous fluid blocks above, up to 15. */
public class TankLevelSensorBlock extends Block{public static final IntegerProperty POWER=IntegerProperty.create("power",0,15);public TankLevelSensorBlock(Properties p){super(p);registerDefaultState(stateDefinition.any().setValue(POWER,0));}@Override public MapCodec<TankLevelSensorBlock> codec(){return RedstoneEngineering.TANK_LEVEL_SENSOR_CODEC.value();}@Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState>b){b.add(POWER);}@Override protected boolean isSignalSource(BlockState s){return true;}@Override protected int getSignal(BlockState s,BlockGetter l,BlockPos p,Direction d){return s.getValue(POWER);}@Override protected void onPlace(BlockState s,Level l,BlockPos p,BlockState o,boolean m){super.onPlace(s,l,p,o,m);if(!l.isClientSide)l.scheduleTick(p,this,1);}@Override protected void tick(BlockState s,ServerLevel l,BlockPos p,RandomSource r){int n=0;for(int i=1;i<=15;i++){BlockPos sample=p.above(i);if(!l.hasChunkAt(sample)||l.getFluidState(sample).isEmpty())break;n++;}if(n!=s.getValue(POWER)){l.setBlock(p,s.setValue(POWER,n),Block.UPDATE_CLIENTS);l.updateNeighborsAt(p,this);}l.scheduleTick(p,this,10);}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player pl,BlockHitResult h){if(!l.isClientSide)pl.displayClientMessage(Component.literal("Tank Level Sensor = "+s.getValue(POWER)+"/15 blocks"),true);return InteractionResult.sidedSuccess(l.isClientSide);}}
